//! Canonical live counts for listed built-in form controls.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><fieldset><input><input type=image><input type=hidden><input type=date><button type=button>Go</button><output></output><select multiple><option>Many</option></select><textarea>seed</textarea></fieldset><object></object></form><form id=other></form><output form=owner></output><output form=other></output></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://form-length.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn form_length_canonical_native_complete_builtin_filter(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var form=document.getElementById('owner'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'length');if(!a||typeof a.get!=='function'||a.set!==undefined||!a.enumerable||!a.configurable||a.get.name!=='get length'||a.get.length!==0||Object.hasOwn(form,'length'))throw 'canonical form length';if(a.get.call(form)!==10||form.length!==10||document.getElementById('other').length!==1)throw 'all builtins and external owners';"#);}
#[test]
fn form_length_inert_current_owner_exact_ids_and_detached_ancestor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var html='http://www.w3.org/1999/xhtml',doc=new Document(),root=doc.createElementNS(html,'div'),a=doc.createElementNS(html,'form'),b=doc.createElementNS(html,'form');doc.appendChild(root);root.appendChild(a);root.appendChild(b);a.id='\ud800';b.id='\udfff';for(var tag of ['button','fieldset','input','object','output','select','textarea']){var c=doc.createElementNS(html,tag);c.setAttribute('form','\ud800');root.appendChild(c);}var image=doc.createElementNS(html,'input');image.setAttribute('type','IMAGE');a.appendChild(image);if(a.length!==7||b.length!==0)throw 'exact connected owners';a.id='changed';if(a.length!==0)throw 'live id ownership';a.id='\ud800';var blocker=doc.createElementNS(html,'div');blocker.id='\ud800';root.insertBefore(blocker,a);if(a.length!==0)throw 'first id blocker';root.removeChild(blocker);if(a.length!==7)throw 'owner recovery';var detached=doc.createElementNS(html,'form'),field=doc.createElementNS(html,'output');field.setAttribute('form','\udfff');detached.appendChild(field);if(detached.length!==1||b.length!==0)throw 'detached ancestor';"#);}
#[test]
fn form_length_readonly_and_genuine_namespace_brands(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var form=document.getElementById('owner'),get=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'length').get,calls=0;form.length={valueOf:function(){calls++;return 1;}};if(form.length!==10||calls)throw 'readonly no conversion';var caught=false;try{(function(){'use strict';form.length=1;})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'readonly strict';for(var bad of [{},Object.create(HTMLFormElement.prototype),document.body,document.createElementNS('urn:foreign','form')]){caught=false;try{get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine form brand';}"#);}

#[test]
fn form_length_opaque_hosts_and_fallback_count_without_public_exposure(){let mut d=crate::html::parse("<html><body><form id=f><object id=opaque><input id=fallback><output></output></object><input type=image><template><input></template><div><input></div></form><script>/*text*/</script></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"if(document.getElementById('opaque')!==null||document.getElementById('fallback')!==null)throw 'opaque public node boundary';var form=document.getElementById('f'),get=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'length').get;if(form.length!==4||get.call(form)!==4)throw 'physical builtins without template content';if(document.getElementById('opaque')!==null||document.getElementById('fallback')!==null)throw 'numeric count exposed opaque nodes';");}
#[test]
fn form_length_inert_namespace_image_filter_and_author_properties(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',form=doc.createElementNS(html,'form'),get=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'length').get;doc.appendChild(form);for(var tag of ['input','input','input','input','meter','progress','div','fieldset','object','output'])form.appendChild(doc.createElementNS(html,tag));var items=form.children;items[0].setAttributeNS('urn:foreign','x:type','image');items[1].setAttributeNS(null,'TYPE','image');items[2].setAttributeNS(null,'type','IMAGE');items[3].setAttributeNS(null,'type',' image');form.appendChild(doc.createElementNS('urn:foreign','input'));Object.defineProperty(form,'elements',{get:function(){throw 'author collection';},configurable:true});Object.defineProperty(form,'children',{get:function(){throw 'author children';},configurable:true});Object.defineProperty(items[0],'form',{get:function(){throw 'author owner';},configurable:true});if(get.call(form)!==6||form.length!==6)throw 'native listed/namespace/image filter';var copy=form.cloneNode(true);if(copy.length!==6)throw 'cloned live count';var other=new Document();if(other.adoptNode(form)!==form||form.length!==6)throw 'adopted live count';"#);}
#[test]
fn form_length_existing_native_named_precedence_and_saved_getter(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var form=document.getElementById('owner'),field=document.createElement('input');field.name='length';form.appendChild(field);var get=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'length').get;if(form.length!==field||get.call(form)!==11)throw 'existing native named precedence';");}
#[test]
fn form_length_saved_child_origin_and_recovery(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var form=document.getElementById('owner'),get=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFormElement.prototype,'length').get;if(get.call(form)!==10)throw 'same origin count';");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.set_location(&crate::navigation::address("https://other-form-length.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let e=p.runtime.execute("get.call(form);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);p.set_location(&crate::navigation::address("https://form-length.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(get.call(form)!==10)throw 'saved count recovery';");}
#[test]
fn form_length_native_refusal_and_numeric_no_string_copy_recovery(){for mode in 0..4{let(mut d,mut f,mut p)=fixture();let n=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()=="owner")).unwrap();p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.form_length_get(node_handle(n)).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=0;p.begin_job();let value=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.form_length_get(node_handle(n)).unwrap();assert!(matches!(value,Value::Number(v)if v==10.0));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}}

#[test]
fn form_length_inert_exact_owner_refusal_and_recovery(){for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),html='http://www.w3.org/1999/xhtml',root=doc.createElementNS(html,'div'),form=doc.createElementNS(html,'form'),output=doc.createElementNS(html,'output'),get=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'length').get;doc.appendChild(root);root.appendChild(form);root.appendChild(output);form.id='target';output.setAttribute('form','target');if(get.call(form)!==1)throw 'warm exact count';");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute("get.call(form);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(get.call(form)!==1||output.getAttribute('form')!=='target')throw 'fresh exact count recovery';");}}
#[test]
fn form_length_implicit_native_count_has_no_copy_string_or_scratch_requirement(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var output of document.querySelectorAll('output[form]'))output.removeAttribute('form');");p.state.rebuild(&d).unwrap();let n=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()=="owner")).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();p.state.copy_work=0;p.state.limits.host.string_bytes=0;p.state.retained_limit=p.state.retained;let value=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.form_length_get(node_handle(n)).unwrap();assert!(matches!(value,Value::Number(v)if v==9.0));assert_eq!(p.state.copy_work,0);assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}
#[test]
fn form_length_legacy_iframe_topology_refuses_without_count_cache(){let mut d=crate::html::parse("<html><body><form id=f><iframe><input></iframe></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);let iframe=(0..d.nodes.len()).find(|&n|tag(&d,n)=="iframe").unwrap();let form=(0..d.nodes.len()).find(|&n|tag(&d,n)=="form").unwrap();if d.nodes[iframe].children.iter().any(|&n|matches!(d.nodes[n].kind,NodeKind::Element{..})){let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.begin_job();let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.form_length_get(node_handle(form)).unwrap_err();assert!(e.contains("iframe")||e.contains("fallback"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);}else{p.begin_job();let value=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.form_length_get(node_handle(form)).unwrap();assert!(matches!(value,Value::Number(v)if v==0.0));}}
